    ($SATQ$80ae6851$SATQ$, $SATQ$2c79adc0-8360-4810-80d7-655a0eb1e8f9$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Algebra$SATQ$, $SATQ$H$SATQ$, $SATQ$H.C.$SATQ$, $SATQ$Linear equations in two variables$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, NULL, $SATQ$<p style="text-align: left;">A producer is creating a video with a length of <math alttext="70"><mn>70</mn>
