    ($SATQ$820ad8e8$SATQ$, $SATQ$2c084f8b-ca91-4384-99bb-5c4f22a12de2$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Algebra$SATQ$, $SATQ$H$SATQ$, $SATQ$H.C.$SATQ$, $SATQ$Linear equations in two variables$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, NULL, $SATQ$<p style="text-align: left;">In a chess tournament, each participant earns <math alttext="1"><mn>1</mn>
</math> point for each game the participant plays that ends in a draw and <math alttext="3"><mn>3</mn>
</math> points for each game the participant wins. A certain participant in this tournament has earned <math alttext="41"><mn>41</mn>
</math> points. Which equation represents this situation, where <math alttext="d"><mi>d</mi>
</math> represents the number of games this participant has played that ended in a draw and <math alttext="w"><mi>w</mi>
</math> represents the number of games this participant has won?</p>$SATQ$, $SATQ$[{"id":"94599e9c-dc35-4073-8193-421bfa8b120a","content":"<p><math alttext=\"d plus 3 w equals 41\"><mi>d</mi><mo>+</mo><mn>3</mn><mi>w</mi><mo>=</mo><mn>41</mn></math></p>"},{"id":"7928b8b5-a261-4ec3-889a-00b3cd88203f","content":"<p><math alttext=\"3 d plus w equals 41\"><mn>3</mn><mi>d</mi><mo>+</mo><mi>w</mi><mo>=</mo><mn>41</mn></math></p>"},{"id":"6b22287d-0569-45f3-8c16-26512cbfefcb","content":"<p><math alttext=\"d plus StartFraction w Over 3 EndFraction equals 41\"><mi>d</mi><mo>+</mo><mfrac><mi>w</mi><mn>3</mn></mfrac><mo>=</mo><mn>41</mn></math></p>"},{"id":"bbd51c8d-737e-41e3-850a-e47db7fa5f74","content":"<p><math alttext=\"StartFraction d Over 3 EndFraction plus w equals 41\"><mfrac><mi>d</mi><mn>3</mn></mfrac><mo>+</mo><mi>w</mi><mo>=</mo><mn>41</mn></math></p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["94599e9c-dc35-4073-8193-421bfa8b120a"]$SATQ$::jsonb, $SATQ$<p style="text-align: left;">Choice A is correct. It&rsquo;s given that each participant earns <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="1"><mn>1</mn></math> point for each game the participant plays that ends in a draw and <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="3"><mn>3</mn></math> points for each game the participant wins. Since <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="d"><mi>d</mi></math> represents the number of games that a certain participant has played that ended in a draw and <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="w"><mi>w</mi></math> represents the number of games this participant has won, this participant has earned a total of <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="1 d plus 3 w"><mn>1</mn><mi>d</mi><mo>+</mo><mn>3</mn><mi>w</mi></math>, or <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="d plus 3 w"><mi>d</mi><mo>+</mo><mn>3</mn><mi>w</mi></math>, points. Since this participant earned <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="41"><mn>41</mn></math> points, the equation <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="d plus 3 w equals 41"><mi>d</mi><mo>+</mo><mn>3</mn><mi>w</mi><mo>=</mo><mn>41</mn></math> represents this situation.</p>
<p style="text-align: left;">Choice B is incorrect. This equation represents the situation where the participant earned&nbsp;<math xmlns="http://www.w3.org/1998/Math/MathML" alttext="3"><mn>3</mn></math> points for each game played that ended in a draw and <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="1"><mn>1</mn></math> point for each game won and earned <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="41"><mn>41</mn></math> points.</p>
<p style="text-align: left;">Choice C is incorrect. This equation represents the situation where the participant earned&nbsp;<math xmlns="http://www.w3.org/1998/Math/MathML" alttext="1"><mn>1</mn></math> point for each game played that ended in a draw and <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="one third"><mfrac><mn>1</mn><mn>3</mn></mfrac></math> point for each game won and earned&nbsp;<math xmlns="http://www.w3.org/1998/Math/MathML" alttext="41"><mn>41</mn></math> points.</p>
<p style="text-align: left;">Choice D is incorrect. This equation represents the situation where the participant earned&nbsp;<math xmlns="http://www.w3.org/1998/Math/MathML" alttext="one third"><mfrac><mn>1</mn><mn>3</mn></mfrac></math> point for each game played that ended in a draw and&nbsp;<math xmlns="http://www.w3.org/1998/Math/MathML" alttext="1"><mn>1</mn></math> point for each game won and earned&nbsp;<math xmlns="http://www.w3.org/1998/Math/MathML" alttext="41"><mn>41</mn></math> points.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"820ad8e8","external_id":"2c084f8b-ca91-4384-99bb-5c4f22a12de2","disclosed_item_id":null,"source":"qbank","vaultid":null,"uId":"e4855b16-5c41-49ab-9621-4501ea0500a8","program":"SAT","test_type":2,"test_type_desc":"Math","primary_class_cd":"H","domain":"Algebra","skill_cd":"H.C.","skill_desc":"Linear equations in two variables","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":null,"stem":"<p style=\"text-align: left;\">In a chess tournament, each participant earns <math alttext=\"1\"><mn>1</mn>\n</math> point for each game the participant plays that ends in a draw and <math alttext=\"3\"><mn>3</mn>\n</math> points for each game the participant wins. A certain participant in this tournament has earned <math alttext=\"41\"><mn>41</mn>\n</math> points. Which equation represents this situation, where <math alttext=\"d\"><mi>d</mi>\n</math> represents the number of games this participant has played that ended in a draw and <math alttext=\"w\"><mi>w</mi>\n</math> represents the number of games this participant has won?</p>","answerOptions":[{"id":"94599e9c-dc35-4073-8193-421bfa8b120a","content":"<p><math alttext=\"d plus 3 w equals 41\"><mi>d</mi><mo>+</mo><mn>3</mn><mi>w</mi><mo>=</mo><mn>41</mn></math></p>"},{"id":"7928b8b5-a261-4ec3-889a-00b3cd88203f","content":"<p><math alttext=\"3 d plus w equals 41\"><mn>3</mn><mi>d</mi><mo>+</mo><mi>w</mi><mo>=</mo><mn>41</mn></math></p>